Usage
reclass(
  cg,
  class = c("DAG", "UG", "PDAG", "CPDAG", "MPDAG", "ADMG", "AG", "MAG", "PAG", "UNKNOWN")
)

Examples

dag &lt;- cgraph(A %--&gt;% X + Y, X %--&gt;% M %--&gt;% Y)
edges(dag)
#&gt;   from to type
#&gt; 1    A  X  --&gt;
#&gt; 2    A  Y  --&gt;
#&gt; 3    X  M  --&gt;
#&gt; 4    M  Y  --&gt;

Examples

dag &lt;- cgraph("A --&gt; X + Y, X --&gt; M --&gt; Y")

cgraph_plot(dag, main = "Mediation") |&gt;
  style_nodes(fill = "lightblue", nodes = parents(dag, "Y")) |&gt;
  style_nodes(shape = "square", nodes = "A") |&gt;
  style_edges(col = "gray60") |&gt;
  style_edges(col = "#DC143C", lwd = 2, from = "X", type = "--&gt;") |&gt;
  style_labels(fontface = "bold", nodes = c("X", "Y")) |&gt;
  label_nodes(X = "Exposure", Y = "Outcome") |&gt;
  style_title(col = "navy")








# Dash every bidirected edge of an ADMG
admg &lt;- cgraph("X --&gt; Y, X &lt;-&gt; Y, Y &lt;-&gt; Z", class = "ADMG")
admg |&gt; style_edges(lty = "dashed", type = "&lt;-&gt;")

Combining options
Here we combine some of the styling above to plot a PAG:

pag &lt;- cgraph(
  "C o-&gt; X, D --&gt; G + Y, X --&gt; D + F, Y --&gt; H, K o-&gt; X, K --&gt; Y",
  class = "PAG"
)

cgraph_plot(pag, layout = "stress", main = "A cool PAG") |&gt;
  style_nodes(fill = "whitesmoke", col = "slategray") |&gt;
  style_nodes(fill = "skyblue", col = "royalblue", nodes = "X") |&gt;
  style_nodes(fill = "gold", col = "darkorange", nodes = "Y") |&gt;
  style_nodes(shape = "square", linestyle = "dashed", nodes = "K") |&gt;
  style_edges(col = "darkslategray") |&gt;
  style_edges(col = "royalblue", lty = "dashed", type = c("o-&gt;", "&lt;-o")) |&gt;
  style_edges(curvature = 0.3, from = "K", to = "Y") |&gt;
  style_edges(label = "cool", from = "K", to = "X") |&gt;
  style_labels(col = "navy", nodes = "X") |&gt;
  style_labels(col = "saddlebrown", nodes = "Y") |&gt;
  style_title(fontsize = 18, col = "navy")

